from collections import deque


class Solution:
    def numOfMinutes(self, n: int, headID: int, manager: list[int], informTime: list[int]) -> int:
        children = [[] for _ in range(n)]
        for emp, boss in enumerate(manager):     # build the tree: O(n)
            if boss != -1:
                children[boss].append(emp)
        best = 0
        queue = deque([(headID, 0)])             # (employee, minute they are informed)
        while queue:                             # each employee once; iterative, no recursion limit
            u, t = queue.popleft()
            best = max(best, t)
            for v in children[u]:
                queue.append((v, t + informTime[u]))   # u needs informTime[u] to reach all reports
        return best

